mapper.select:
SELECT c.*, c.agent_id as owner_agent_id, a.nickname as owner_agent_name, a.avatar as owner_agent_avatar, v.nickname as visitor_nickname, v.star as visitor_star, v.star_time as visitor_star_time FROM cs_conversation c LEFT JOIN cs_agent a ON c.agent_id = a.id LEFT JOIN cs_visitor v ON c.user_id = v.user_id AND c.app_id = v.app_id
AND (c.deleted = 0 OR c.deleted IS NULL)
AND c.agent_id = #{filterAgentId}
AND c.agent_id = #{agentId} AND c.status != 2
AND EXISTS ( SELECT 1 FROM cs_collaborator col WHERE col.conversation_id = c.id AND col.agent_id = #{agentId} AND col.leave_time IS NULL AND col.role != 0 )
AND c.status = 0 AND (c.agent_id IS NULL OR c.agent_id = '')
AND c.status = 2
AND c.agent_id = #{agentId}
AND (c.agent_id = #{agentId} OR c.agent_id IS NULL OR c.status = 0) AND c.status != 2
AND c.status = #{status}
AND c.id = #{id}
AND c.user_id LIKE CONCAT('%', #{userId}, '%')
AND c.end_type = #{endType}
AND c.satisfaction = #{satisfaction}
AND c.source LIKE CONCAT('%', #{source}, '%')
AND c.landing_page LIKE CONCAT('%', #{landingPage}, '%')
AND c.referrer_page LIKE CONCAT('%', #{referrerPage}, '%')
AND c.create_time >= #{createTimeBegin}
AND c.create_time <= CONCAT(#{createTimeEnd}, ' 23:59:59')
AND c.end_time >= #{endTimeBegin}
AND c.end_time <= CONCAT(#{endTimeEnd}, ' 23:59:59')
ORDER BY c.id DESC
